// Perception System для AI агента
interface PerceptionInput {
  type: 'text' | 'image' | 'audio' | 'structured';
  data: any;
  metadata?: {
    timestamp: Date;
    source: string;
    priority: number;
  };
}

class PerceptionLayer {
  private processors: Map<string, InputProcessor>;

  constructor() {
    this.processors = new Map([
      ['text', new TextProcessor()],
      ['image', new VisionProcessor()],
      ['audio', new AudioProcessor()],
      ['structured', new DataProcessor()]
    ]);
  }

  async perceive(inputs: PerceptionInput[]): Promise<ProcessedPercept[]> {
    // Параллельная обработка всех входов
    const processed = await Promise.all(
      inputs.map(input => this.processInput(input))
    );

    // Объединение и нормализация
    return this.normalize(processed);
  }

  private async processInput(input: PerceptionInput): Promise<ProcessedPercept> {
    const processor = this.processors.get(input.type);
    if (!processor) {
      throw new Error(`Unknown input type: ${input.type}`);
    }

    // Применяем соответствующий процессор
    const features = await processor.extract(input.data);

    return {
      type: input.type,
      features,
      metadata: input.metadata,
      embedding: await this.generateEmbedding(features)
    };
  }

  private normalize(percepts: ProcessedPercept[]): ProcessedPercept[] {
    // Нормализация и фильтрация
    return percepts
      .filter(p => p.features.length > 0)
      .sort((a, b) => (b.metadata?.priority ?? 0) - (a.metadata?.priority ?? 0));
  }

  private async generateEmbedding(features: any): Promise<number[]> {
    // Генерация векторного представления
    // Используется для семантического поиска и сравнения
    return embedModel.encode(features);
  }
}

// Продвинутая система планирования
interface Task {
  id: string;
  description: string;
  dependencies: string[];
  estimatedCost: number;
  priority: number;
}

interface Plan {
  goal: string;
  tasks: Task[];
  executionOrder: string[];
}

class AdvancedPlanner {
  constructor(
    private llm: LanguageModel,
    private knowledgeBase: KnowledgeBase
  ) {}

  async createPlan(goal: string, constraints?: Constraints): Promise<Plan> {
    // 1. Декомпозиция цели
    const tasks = await this.decomposeGoal(goal);

    // 2. Анализ зависимостей
    const taskGraph = this.buildDependencyGraph(tasks);

    // 3. Оптимизация порядка выполнения
    const executionOrder = this.optimizeExecution(taskGraph, constraints);

    return {
      goal,
      tasks,
      executionOrder
    };
  }

  private async decomposeGoal(goal: string): Promise<Task[]> {
    // Используем LLM для декомпозиции
    const prompt = `
      Разбей следующую цель на конкретные подзадачи:

      Цель: ${goal}

      Для каждой подзадачи укажи:
      - Описание
      - Зависимости (от каких других задач зависит)
      - Приоритет (1-10)

      Формат ответа: JSON
    `;

    const response = await this.llm.generate(prompt);
    const tasks = JSON.parse(response);

    // Добавляем оценку стоимости
    for (const task of tasks) {
      task.estimatedCost = await this.estimateTaskCost(task);
    }

    return tasks;
  }

  private buildDependencyGraph(tasks: Task[]): TaskGraph {
    const graph = new TaskGraph();

    for (const task of tasks) {
      graph.addNode(task.id, task);
    }

    for (const task of tasks) {
      for (const depId of task.dependencies) {
        graph.addEdge(depId, task.id);
      }
    }

    // Проверка на циклы
    if (graph.hasCycles()) {
      throw new Error('Циклические зависимости в плане!');
    }

    return graph;
  }

  private optimizeExecution(
    graph: TaskGraph,
    constraints?: Constraints
  ): string[] {
    // Топологическая сортировка с учетом приоритетов
    const sorted = graph.topologicalSort();

    // Оптимизация под constraints
    if (constraints?.maxParallelTasks) {
      return this.parallelizeExecution(sorted, constraints.maxParallelTasks);
    }

    if (constraints?.maxTime) {
      return this.optimizeForTime(sorted, constraints.maxTime);
    }

    // По умолчанию - сортировка по приоритету
    return this.sortByPriority(sorted);
  }

  // Адаптивное перепланирование
  async replan(
    originalPlan: Plan,
    executedTasks: string[],
    failedTask?: string,
    newContext?: any
  ): Promise<Plan> {
    // Анализируем, что пошло не так
    const analysis = await this.analyzeFailure(failedTask, newContext);

    // Оставшиеся задачи
    const remainingTasks = originalPlan.tasks.filter(
      t => !executedTasks.includes(t.id)
    );

    // Создаем альтернативные задачи если нужно
    if (failedTask && analysis.needsAlternative) {
      const alternative = await this.generateAlternativeTask(
        originalPlan.tasks.find(t => t.id === failedTask)!,
        analysis.reason
      );
      remainingTasks.push(alternative);
    }

    // Пересоздаем план
    return this.createPlan(
      originalPlan.goal,
      { existingTasks: remainingTasks }
    );
  }
}

// Комплексная система памяти
class AgentMemorySystem {
  private shortTerm: ConversationBuffer;
  private longTerm: VectorStore;
  private episodic: EpisodicStore;
  private semantic: KnowledgeGraph;

  constructor() {
    this.shortTerm = new ConversationBuffer(maxTokens: 8000);
    this.longTerm = new VectorStore({
      provider: 'pinecone',
      dimension: 1536,  // OpenAI embeddings
      metric: 'cosine'
    });
    this.episodic = new EpisodicStore();
    this.semantic = new KnowledgeGraph();
  }

  async remember(query: string, context?: any): Promise<Memory[]> {
    // Многоуровневый поиск в памяти
    const [shortTermResults, longTermResults, episodicResults] = 
      await Promise.all([
        this.searchShortTerm(query),
        this.searchLongTerm(query),
        this.searchEpisodic(query)
      ]);

    // Объединение и ранжирование результатов
    const allMemories = [
      ...shortTermResults,
      ...longTermResults,
      ...episodicResults
    ];

    return this.rankMemories(allMemories, query, context);
  }

  async store(interaction: Interaction): Promise<void> {
    // Сохранение в краткосрочную память
    this.shortTerm.add(interaction);

    // Определяем важность
    const importance = await this.assessImportance(interaction);

    // Если важно - сохраняем в долгосрочную
    if (importance > 0.7) {
      const embedding = await this.generateEmbedding(
        interaction.content
      );

      await this.longTerm.upsert({
        id: interaction.id,
        vector: embedding,
        metadata: {
          content: interaction.content,
          timestamp: interaction.timestamp,
          importance,
          tags: interaction.tags
        }
      });

      // Сохранение как эпизод
      await this.episodic.store({
        what: interaction.content,
        when: interaction.timestamp,
        where: interaction.context,
        why: interaction.intent,
        outcome: interaction.result
      });
    }

    // Извлечение знаний для semantic memory
    const knowledge = await this.extractKnowledge(interaction);
    if (knowledge) {
      await this.semantic.addKnowledge(knowledge);
    }
  }

  private async searchLongTerm(query: string): Promise<Memory[]> {
    const queryEmbedding = await this.generateEmbedding(query);

    const results = await this.longTerm.query({
      vector: queryEmbedding,
      topK: 5,
      filter: {
        // Можно фильтровать по времени, тегам и т.д.
      }
    });

    return results.matches.map(match => ({
      content: match.metadata.content,
      relevance: match.score,
      timestamp: match.metadata.timestamp,
      type: 'long-term'
    }));
  }

  private async assessImportance(interaction: Interaction): Promise<number> {
    // Факторы важности:
    const factors = {
      userFeedback: interaction.feedback ? 0.3 : 0,
      novelty: await this.calculateNovelty(interaction),
      emotionalSalience: this.detectEmotion(interaction),
      goalRelevance: await this.assessGoalRelevance(interaction)
    };

    return Object.values(factors).reduce((a, b) => a + b, 0) / 4;
  }

  // Периодическая консолидация памяти
  async consolidate(): Promise<void> {
    // 1. Удаление дубликатов
    await this.deduplicateMemories();

    // 2. Обобщение связанных воспоминаний
    const clusters = await this.clusterMemories();
    for (const cluster of clusters) {
      const summary = await this.summarizeCluster(cluster);
      await this.store(summary);
    }

    // 3. Забывание неважных воспоминаний
    await this.forgetIrrelevant();

    // 4. Укрепление важных паттернов
    await this.reinforcePatterns();
  }

  private async forgetIrrelevant(): Promise<void> {
    // Decay function: важность уменьшается со временем
    const now = Date.now();
    const memories = await this.longTerm.list();

    for (const memory of memories) {
      const age = now - memory.metadata.timestamp;
      const ageInDays = age / (1000 * 60 * 60 * 24);

      // Экспоненциальный decay
      const decayedImportance = 
        memory.metadata.importance * Math.exp(-ageInDays / 30);

      if (decayedImportance < 0.1) {
        // Забываем
        await this.longTerm.delete(memory.id);
      } else {
        // Обновляем важность
        await this.longTerm.update(memory.id, {
          importance: decayedImportance
        });
      }
    }
  }
}

# Продвинутая система выполнения действий
from typing import Any, Callable, Dict, List
from dataclasses import dataclass

@dataclass
class Tool:
    name: str
    description: str
    function: Callable
    parameters: Dict[str, Any]
    requires_confirmation: bool = False

class ActionExecutor:
    def __init__(self):
        self.tools = {}
        self.execution_history = []
        self.safety_checker = SafetyChecker()

    def register_tool(self, tool: Tool):
        """Регистрация нового инструмента"""
        self.tools[tool.name] = tool

    async def execute(self, action: Action) -> ActionResult:
        """Выполнение действия с полным циклом обработки"""

        # 1. Валидация
        validation = await self.validate_action(action)
        if not validation.valid:
            return ActionResult(
                success=False,
                error=validation.error
            )

        # 2. Проверка безопасности
        safety_check = await self.safety_checker.check(action)
        if not safety_check.safe:
            return ActionResult(
                success=False,
                error=f"Safety check failed: {safety_check.reason}"
            )

        # 3. Подтверждение если требуется
        tool = self.tools[action.tool_name]
        if tool.requires_confirmation:
            confirmed = await self.request_confirmation(action)
            if not confirmed:
                return ActionResult(
                    success=False,
                    cancelled=True
                )

        # 4. Выполнение
        try:
            result = await self.execute_tool(
                tool,
                action.parameters
            )

            # 5. Запись в историю
            self.execution_history.append({
                'action': action,
                'result': result,
                'timestamp': datetime.now()
            })

            return ActionResult(
                success=True,
                data=result
            )

        except Exception as e:
            # Обработка ошибок
            return await self.handle_error(action, e)

    async def execute_with_retry(
        self,
        action: Action,
        max_retries: int = 3
    ) -> ActionResult:
        """Выполнение с retry логикой"""

        for attempt in range(max_retries):
            result = await self.execute(action)

            if result.success:
                return result

            # Анализ ошибки
            if result.error and 'rate limit' in result.error.lower():
                # Exponential backoff
                await asyncio.sleep(2 ** attempt)
                continue

            if result.error and 'timeout' in result.error.lower():
                # Увеличиваем timeout
                action.timeout *= 2
                continue

            # Неисправимая ошибка
            break

        return result

    async def execute_parallel(
        self,
        actions: List[Action]
    ) -> List[ActionResult]:
        """Параллельное выполнение независимых действий"""

        # Проверка зависимостей
        independent_groups = self.group_by_dependencies(actions)

        results = []
        for group in independent_groups:
            # Группа выполняется параллельно
            group_results = await asyncio.gather(*[
                self.execute(action) for action in group
            ])
            results.extend(group_results)

        return results

